-- sets up initial states of `images` and `bars`
(function (images)
  local function setupimage (t, prefix)
    for key, val in pairs(t) do
      local str = string.format("%s.%s", prefix, key)
      if type(val) == 'table' then
        setupimage(val, str)
      else
        local surface, width, height = bolt.createsurfacefrompng(str)
        t[key] = { width = width, height = height, surface = surface }
      end
    end
  end
  setupimage(images, "assets")
end)(images)

numparse = function (num, size)
  local number_to_process
  if type(num) ~= "number" then
      number_to_process = 0
  else
      -- Optional: Cap the number within the supported range (0-99)
      number_to_process = math.max(0, math.min(99, num))
  end

    -- Format the number into a two-digit string (e.g., 5 -> "05")
  local num_str = string.format("%02d", number_to_process)

  -- Return the individual characters
  local digit1_val = tonumber(num_str:sub(1, 1))
  local digit2_val = tonumber(num_str:sub(2, 2))

  -- Calculate the source X coordinate in the image
  local digit1 = digit1_val * size
  local digit2 = digit2_val * size

  return digit1, digit2
end

